struct Point: Sendable {
    var x: Int
    var y: Int
}

func test() async {
    let p1 = Point(x: 10, y: 20)
    let t = Task {
        var p2 = p1
        p2.x = 50
        return p2.x
    }
    let res = await t.value
    print("\(p1.x) \(res)")
}

await test()

final class ImmutableMessage: Sendable {
    let text: String
    let senderId: Int

    init(text: String, senderId: Int) {
        self.text = text
        self.senderId = senderId
    }
}

func check() async {
    let msg = ImmutableMessage(text: "Hello", senderId: 7)
    let task = Task {
        return "\(msg.senderId): \(msg.text)"
    }
    let result = await task.value
    print(result)
}

await check()

actor SafeCounter {
    var count = 0
    func add() { count += 1 }
    func value() -> Int { count }
}

func run() async {
    let counter = SafeCounter()
    let t = Task {
        await counter.add()
        return await counter.value()
    }
    let res = await t.value
    print("Result: \(res)")
}

await run()

enum JobStatus: Sendable {
    case pending
    case active(id: Int)
}

func checkStatus() async {
    let status = JobStatus.active(id: 99)
    let task = Task {
        switch status {
        case .pending:
            return "Pending"
        case .active(let id):
            return "Active \(id)"
        }
    }
    let res = await task.value
    print(res)
}

await checkStatus()

func executeAsync(operation: @escaping @Sendable () -> Int) async -> Int {
    let task = Task {
        operation()
    }
    return await task.value
}

func testClosure() async {
    let multiplier = 5
    let result = await executeAsync {
        multiplier * 10
    }
    print("Total: \(result)")
}

await testClosure()

func processNames(_ names: [String]) async {
    let task = Task {
        names.joined(separator: ", ")
    }
    let combined = await task.value
    print("Items: \(combined)")
}

await processNames(["Swift", "iOS", "Xcode"])

struct TaskRecord: Sendable {
    let title: String
    let priority: Int
}

func inspectRecord() async {
    let record = TaskRecord(title: "Refactor", priority: 1)
    let backgroundTask = Task {
        return "\(record.title) with priority \(record.priority)"
    }
    let output = await backgroundTask.value
    print(output)
}

await inspectRecord()

struct DeviceSetting: Sendable {
    var volume: Int

    mutating func increase() {
        volume += 5
    }
}

func checkSetting() async {
    let setting = DeviceSetting(volume: 20)
    let task = Task {
        var copy = setting
        copy.increase()
        return copy.volume
    }
    let newVolume = await task.value
    print("Old: \(setting.volume), New: \(newVolume)")
}

await checkSetting()

