struct ScoreCard: Sendable {
    let player: String
    let points: Int

    func formatted() -> String {
        "\(player): \(points) pts"
    }
}

func printScore() async {
    let card = ScoreCard(player: "Alex", points: 150)
    let task = Task {
        card.formatted()
    }
    let res = await task.value
    print(res)
}

await printScore()

